#!/bin/sh
# The CEF bindings (src/cef_capi.odin, src/cef_gen.odin) against the real
# CEF headers: each function's parameters and result, each struct's size
# and field offsets. CEF_DIR: a CEF binary distribution, or a
# chromiumembedded/cef checkout at the pinned branch with include/capi
# generated by its tools/translator.py (the git tree has no capi headers).
# CEF_CFLAGS: extra -I for anything else the headers include.
set -eu
here=$(cd "$(dirname "$0")/.." && pwd)
cd "$here"
[ -n "${CEF_DIR:-}" ] || { echo "CEF_DIR is not set" >&2; exit 2; }
. tools/cef_headers.sh
python3 abi/check.py --headers "$CEF_HEADERS" --cflags "$CEF_FLAGS" --import iris="$here/src" src/cef_capi.odin src/cef_gen.odin
